INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(46111, 'Numbers 16:46', 'Numbers', 16, 46, 'بیا موسی هارون ته وویل: «خپل د اور لوښی راواخله او په هغه کې د قربانۍ د ځای څخه سره سکاره واچوه او په سکارو باندې لږه خوشبویي واچوه. بیا د هغه سره سمدلاسه خلکو ته ورشه او د هغوی دپاره کفاره ادا کړه. زر شه! ځکه چې څښتن ډېر په قهر دی او وبا لا د مخکې څخه شروع شوې ده!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_46.mp3', '', 1761754199, 1761754199),
(46112, 'Numbers 16:47', 'Numbers', 16, 47, 'نو څنګه چې موسی ویلي وو هارون هماغسې وکړل او د خلکو منځ ته یې ورمنډه کړه. وبا لا مخکې په خلکو کې شروع شوې وه، خو هارون خوشبویي وړاندې کړه او د هغوی دپاره یې کفاره ادا کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_47.mp3', '', 1761754199, 1761754199),
(46113, 'Numbers 16:48', 'Numbers', 16, 48, 'هغه د مړو او ژوندیو ترمنځ ودرېده او وبا بنده شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_48.mp3', '', 1761754199, 1761754199),
(46114, 'Numbers 16:49', 'Numbers', 16, 49, 'خو ۱۴۷۰۰ تنه اسراییلیان مړه شوي وو، پرته له هغو خلکو څخه چې د قورح او د هغه د پیروانو سره مړه شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_49.mp3', '', 1761754199, 1761754199),
(46115, 'Numbers 16:50', 'Numbers', 16, 50, 'کله چې وبا ودرېدله، هارون بېرته د سپېڅلې خېمې دروازې ته موسی ته ورستون شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers16_verse_50.mp3', '', 1761754199, 1761754199),
(46116, 'Psalms 142:1', 'Psalms', 142, 1, 'زه فریاد کوم څښتن ته د رحم دپاره ورته کومه زارۍ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms142_verse_1.mp3', '', 1761754199, 1761754199),
(46117, 'Psalms 142:2', 'Psalms', 142, 2, 'شکایتونه خپل ټول وړاندې کوم هغه ته تکلیفونه خپل ټول بیانوم هغه ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms142_verse_2.mp3', '', 1761754199, 1761754199),
(46118, 'Psalms 142:3', 'Psalms', 142, 3, 'کله چې روح زما کمزوری شي نو ته پوهېږې چې په کومه لاره لاړ شمه زه په هغه لاره چې روان یمه زه زما دښمنانو راته ایښی پټ دام', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms142_verse_3.mp3', '', 1761754199, 1761754199),
(46119, 'Psalms 142:4', 'Psalms', 142, 4, 'کله چې خپل شاوخوا ته وګورم زه هېڅوک نه وینم چې زما کومک ته راشي هېڅ پناه ځای نه لرم نشته هېڅوک چې په ما پام وکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms142_verse_4.mp3', '', 1761754199, 1761754199),
(46120, 'Psalms 142:5', 'Psalms', 142, 5, 'ای څښتنه، زه فریاد کومه تاته ځکه چې ته یې پناه ځای زما په دې ژوند کې چې څه غواړم هغه ته یې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms142_verse_5.mp3', '', 1761754199, 1761754199),
(46121, 'Psalms 142:6', 'Psalms', 142, 6, 'زما فریاد واوره کومک دپاره ځکه چې زه خوار او زار شوی یمه ماته نجات راکړه د خپلو دښمنانو څخه ځکه هغوی دي ډېر قوي زما نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms142_verse_6.mp3', '', 1761754199, 1761754199),
(46122, 'Psalms 142:7', 'Psalms', 142, 7, 'ته مې خلاص کړه له دې زندانه څخه نو بیا به زه ستا د نامه ثنا او صفت کومه ستا د نېکانو په غونډه کې ځکه چې ما سره دې کړی احسان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms142_verse_7.mp3', '', 1761754199, 1761754199),
(46123, 'Leviticus 22:1', 'Leviticus', 22, 1, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_1.mp3', '', 1761754199, 1761754199),
(46124, 'Leviticus 22:2', 'Leviticus', 22, 2, '«هارون او د هغه زامنو ته ووایه چې د هغو پاکو نذرانو درناوی وکړي چې اسراییلیان یې ماته وقف کوي، ترڅو هغوی زما سپېڅلی نوم سپک نه کړي. زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_2.mp3', '', 1761754199, 1761754199),
(46125, 'Leviticus 22:3', 'Leviticus', 22, 3, 'که چېرې ستاسو د اولادې څخه کوم یو د ناپاکۍ په حال کې هغو سپېڅلو نذرانو ته ورنژدې شي چې د اسراییلو قوم ماته وقف کړې دي، هغه بیا هېڅکله د قربانۍ په ځای کې خدمت نه شي کولای. دا خبره به تل ترتله عملي کیږي. زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_3.mp3', '', 1761754199, 1761754199),
(46126, 'Leviticus 22:4', 'Leviticus', 22, 4, 'که چېرې د هارون د اولادې څخه کوم یو د پوستکي په ساري ناروغۍ اخته وي یا د بدن څخه یې زوه راوځي، هغه تر هغه وخته پورې دا پاکې نذرانې نه شي خوړلی، ترڅو پورې چې پاک نه شي. هر کاهن چې داسې کوم شي ته لاس وروړي چې د مړي سره د لګېدلو په وسیله ناپاک شوی وي یا که چېرې د کاهن څخه مني ووځي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_4.mp3', '', 1761754199, 1761754199),
(46127, 'Leviticus 22:5', 'Leviticus', 22, 5, 'یا که چېرې هغه په ناپاک حیوان یا ناپاک کس باندې لاس وهلی وي، نو هغه ناپاک کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_5.mp3', '', 1761754199, 1761754199),
(46128, 'Leviticus 22:6', 'Leviticus', 22, 6, 'هر کاهن چې دغو شیانو ته لاس وروړي هغه به ناپاک شي، نو هغه تر ماښامه پورې ناپاک پاتې کیږي. بیاهم هغه پاکې نذرانې نه شي خوړلی، ترڅو پورې چې غسل ونه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_6.mp3', '', 1761754199, 1761754199),
(46129, 'Leviticus 22:7', 'Leviticus', 22, 7, 'کله چې لمر پرېوځي، هغه به پاک شي او له هغې څخه وروسته هغه کولای شي چې پاکې نذرانې وخوري، ځکه چې دا د هغه خواړه دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_7.mp3', '', 1761754199, 1761754199),
(46130, 'Leviticus 22:8', 'Leviticus', 22, 8, 'هغه دې د داسې حیوان غوښه ونه خوري چې په خپل مرګ مړ شوی وي یا د وحشي حیواناتو په وسیله وژل شوی وي، په دې باندې به هغه ناپاک شي. زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_8.mp3', '', 1761754199, 1761754199),
(46131, 'Leviticus 22:9', 'Leviticus', 22, 9, 'ټول کاهنان دې زما د مقرراتو څخه چې هغوی ته مې ورکړي دي، پیروي وکړي. که نه، نو هغوی به ګناهکاران او مړه شي، ځکه چې هغوی سپېڅلو مقرراتو ته په سپکه سترګه کتلي دي. زه څښتن یم چې هغوی سپېڅلي کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_9.mp3', '', 1761754199, 1761754199),
(46132, 'Leviticus 22:10', 'Leviticus', 22, 10, 'څوک چې د کاهن د کورنۍ غړی نه وي، هغه پاکې نذرانې نه شي خوړلی. د کاهن مېلمه یا مزدور هم هغه نه شي خوړلی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_10.mp3', '', 1761754199, 1761754199),
(46133, 'Leviticus 22:11', 'Leviticus', 22, 11, 'خو که چېرې یو کاهن په خپلو پیسو باندې یو غلام اخیستی وي یا که چېرې یو غلام د هغه په کورنۍ کې زېږېدلی وي، هغه غلام کولای شي چې هغه خواړه وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_11.mp3', '', 1761754199, 1761754199),
(46134, 'Leviticus 22:12', 'Leviticus', 22, 12, 'که چېرې د یو کاهن لور د یو داسې سړي سره واده وکړي چې هغه کاهن نه وي، هغه نه شي کولای چې پاکې نذرانې وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_12.mp3', '', 1761754199, 1761754199),
(46135, 'Leviticus 22:13', 'Leviticus', 22, 13, 'خو که چېرې د یو کاهن لور کونډه یا طلاقه شوې وي او اولادونه ونه لري او بېرته راشي او د خپل پلار په کور کې اوسیږي، هغه کولای شي چې هغه خواړه وخوري چې د هغې پلار یې د کاهن په توګه تر لاسه کوي. په هر حال د کاهن د کورنۍ د غړو څخه پرته هېڅوک نه شي کولای چې هغه وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_13.mp3', '', 1761754199, 1761754199),
(46136, 'Leviticus 22:14', 'Leviticus', 22, 14, 'که چېرې داسې خلک چې د کاهن د کورنۍ غړي نه وي په سهوې سره پاکې نذرانې وخوري، هغوی باید کاهن ته د اضافه شلو فیصدو سره پوره تاوان ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_14.mp3', '', 1761754199, 1761754199),
(46137, 'Leviticus 22:17', 'Leviticus', 22, 17, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_17.mp3', '', 1761754199, 1761754199),
(46138, 'Leviticus 22:18', 'Leviticus', 22, 18, '«هارون او د هغه د زامنو او ټولو اسراییلیانو سره خبرې وکړه او ورته ووایه: که چېرې ستاسو څخه یو کس که هغه یو اسراییلی یا یو داسې پردی کس وي چې په اسراییلو کې اوسیږي، ماته د سوځېدونکې نذرانې دپاره یو سوغات وړاندې کوي، که هغه د نذر د ورکولو په توګه وي یا د خپلې خوښې نذرانه وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_18.mp3', '', 1761754199, 1761754199),
(46139, 'Leviticus 22:19', 'Leviticus', 22, 19, 'تاسو باید د پادې یا رمې څخه یو نر حیوان وړاندې کړئ چې کوم عیب په کې نه وي، د دې دپاره چې هغه ستاسو په خاطر قبول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_19.mp3', '', 1761754199, 1761754199),
(46140, 'Leviticus 22:20', 'Leviticus', 22, 20, 'که چېرې تاسو یو داسې حیوان وړاندې کړئ چې کوم عیب په کې وي، زه څښتن به هغه قبول نه کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_20.mp3', '', 1761754199, 1761754199),
(46141, 'Leviticus 22:21', 'Leviticus', 22, 21, 'کله چې یو کس څښتن ته د رمې او یا پادې څخه د سلامتۍ نذرانه راوړي چې یو نذر ورکړي یا د خپلې خوښې نذرانې په توګه وي، د دې دپاره چې د منلو وړ وي، نو په هغې کې باید هېڅ عیب نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_21.mp3', '', 1761754199, 1761754199),
(46142, 'Leviticus 22:22', 'Leviticus', 22, 22, 'څښتن ته داسې حیوان مه وړاندې کوئ چې ړوند، ګوډ یا معیوب وي، زخم ولري او یا د پوستکي په دوامداره ناروغۍ اخته وي. هغه د قربانۍ په ځای باندې د یوې داسې نذرانې په توګه مه ږدئ چې په اور باندې څښتن ته تیاریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_22.mp3', '', 1761754199, 1761754199),
(46143, 'Leviticus 22:23', 'Leviticus', 22, 23, 'که څه هم تاسو کولای شئ چې د خپلې خوښې نذرانې په توګه یو حیوان چې بې ډوله یا کوچنی وي وړاندې کړئ، خو هغه به د نذر په توګه قبول نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_23.mp3', '', 1761754199, 1761754199),
(46144, 'Leviticus 22:24', 'Leviticus', 22, 24, 'څښتن ته هېڅ داسې حیوان مه وړاندې کوئ چې خصیه یې ټکول شوې، پرېکړل شوې، زخمي شوې یا ویستل شوې وي. تاسو باید په خپله خاوره کې داسې کار ونه کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_24.mp3', '', 1761754199, 1761754199),
(46145, 'Leviticus 22:25', 'Leviticus', 22, 25, 'تاسو باید د پردیو خلکو څخه داسې حیوانات وانخلئ چې د خوړو د نذرانو په توګه یې وړاندې کړئ. هغه به ستاسو دپاره قبول نه شي، ځکه چې هغه بې ډوله دي یا عیبونه په کې دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_25.mp3', '', 1761754199, 1761754199),
(46146, 'Leviticus 22:26', 'Leviticus', 22, 26, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_26.mp3', '', 1761754199, 1761754199),
(46147, 'Leviticus 22:27', 'Leviticus', 22, 27, '«کله چې یو خوسی، یو وری یا یوه وزه پیدا شي، د خپلې مور سره دې اووه ورځې پاتې شي. له اتمې ورځې څخه به هغه د یوې داسې نذرانې په توګه د منلو وړ وي چې څښتن ته په اور باندې تیاریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_27.mp3', '', 1761754199, 1761754199),
(46148, 'Leviticus 22:28', 'Leviticus', 22, 28, 'یوه غوا او د هغې خوسی یا یوه مېږه او د هغې وری یا یوه وزه او د هغې بچی په یوه ورځ مه حلالوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_28.mp3', '', 1761754199, 1761754199),
(46149, 'Leviticus 22:29', 'Leviticus', 22, 29, 'کله چې تاسو څښتن ته د شکرانې یوه نذرانه قرباني کوئ، نو د مقرراتو څخه پیروي وکړئ، ترڅو هغه ستاسو په خاطر قبوله شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_29.mp3', '', 1761754199, 1761754199),
(46150, 'Leviticus 22:30', 'Leviticus', 22, 30, 'هغه باید په هماغه ورځ وخوړل شي، د هغې څخه تر سهاره پورې هېڅ شی مه پرېږدئ. زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_30.mp3', '', 1761754199, 1761754199),
(46151, 'Leviticus 22:31', 'Leviticus', 22, 31, 'زما د حکمونو څخه پیروي وکړئ. زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_31.mp3', '', 1761754199, 1761754199),
(46152, 'Leviticus 22:32', 'Leviticus', 22, 32, 'زما سپېڅلی نوم مه سپکوئ. د اسراییلو ټول قوم باید د دې خبرې اقرار وکړي چې زه سپېڅلی یم. زه څښتن یم چې تاسو سپېڅلي کوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_32.mp3', '', 1761754199, 1761754199),
(46153, 'Leviticus 22:33', 'Leviticus', 22, 33, 'او تاسو مې د دې دپاره له مصر څخه راوویستلئ چې ستاسو خدای اوسم. زه څښتن یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus22_verse_33.mp3', '', 1761754199, 1761754199),
(46154, 'Leviticus 15:1', 'Leviticus', 15, 1, 'څښتن موسی او هارون ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_1.mp3', '', 1761754199, 1761754199),
(46155, 'Leviticus 15:2', 'Leviticus', 15, 2, '«د اسراییلیانو سره خبرې وکړئ او ورته ووایئ: کله چې د یو سړي د تناسلي الې څخه زوه راووځي، هغه زوه ناپاکه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_2.mp3', '', 1761754199, 1761754199),
(46156, 'Leviticus 15:3', 'Leviticus', 15, 3, 'که دا زوه د هغه د تناسلي الې څخه رابهیږي یا دا بهېدل د پړسوب له امله بند شوي وي، هغه به ناپاک کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_3.mp3', '', 1761754199, 1761754199),
(46157, 'Leviticus 15:4', 'Leviticus', 15, 4, 'که داسې سړی چې زوه ورڅخه راوځي، که هغه په هرې بسترې باندې څملي او یا په هر شي باندې کښېني هغه شی به ناپاک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_4.mp3', '', 1761754199, 1761754199),
(46158, 'Leviticus 15:5', 'Leviticus', 15, 5, 'هرڅوک چې د هغه د بسترې سره ولګیږي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_5.mp3', '', 1761754199, 1761754199),
(46159, 'Leviticus 15:6', 'Leviticus', 15, 6, 'یا په هغه شي باندې کښېني چې هغه سړی ورباندې ناست ؤ، نو هغه کس باید خپل کالي ووینځي او غسل دې وکړي، خو هغه به تر ماښامه پورې ناپاک پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_6.mp3', '', 1761754199, 1761754199),
(46160, 'Leviticus 15:7', 'Leviticus', 15, 7, 'هرڅوک چې د هغه سړي سره ولګیږي، باید خپل کالي ووینځي او غسل دې وکړي، خو هغه به تر ماښامه پورې ناپاک پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_7.mp3', '', 1761754199, 1761754199),
(46161, 'Leviticus 15:8', 'Leviticus', 15, 8, 'که چېرې هغه کس چې زوه ورڅخه راوځي په داسې یو کس باندې چې هغه پاک وي لیاړې واچوي، هغه سړی باید خپل کالي ووینځي او غسل دې وکړي، خو هغه به تر ماښامه پورې ناپاک پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_8.mp3', '', 1761754199, 1761754199),
(46162, 'Leviticus 15:9', 'Leviticus', 15, 9, 'که دا سړی په کوم زین باندې کښېني، هغه به ناپاک شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_9.mp3', '', 1761754199, 1761754199),
(46163, 'Leviticus 15:10', 'Leviticus', 15, 10, 'او هرڅوک چې د هغه شي سره ولګیږي چې دا سړی ورباندې ناست ؤ، هغه به تر ماښامه پورې ناپاک وي. هرڅوک چې داسې شیان راپورته کړي، هغه باید خپل کالي ووینځي او غسل دې وکړي، خو تر ماښامه پورې به ناپاک پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_10.mp3', '', 1761754199, 1761754199),
(46164, 'Leviticus 15:11', 'Leviticus', 15, 11, 'که چېرې یو سړی چې زوه ورڅخه راووځي او خپل لاسونه یې نه وي وینځلي، په کوم بل کس باندې ولګیږي، نو هغه څوک چې دی ورسره لګېدلی دی باید خپل کالي ووینځي او غسل دې وکړي، خو هغه به تر ماښامه پورې ناپاک پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_11.mp3', '', 1761754199, 1761754199),
(46165, 'Leviticus 15:12', 'Leviticus', 15, 12, 'که هغه سړی چې زوه ورڅخه راوځي د خټو هر لوښي ته لاس وروړي، هغه باید مات شي او که د لرګي کوم لوښي ته لاس وروړي، هغه باید ووینځل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_12.mp3', '', 1761754199, 1761754199),
(46166, 'Leviticus 15:13', 'Leviticus', 15, 13, 'له هغې وروسته چې د زوې د راوتلو څخه د دغه سړي علاج وشي، هغه باید اووه ورځې صبر وکړي او بیا دې د چینې په تازه اوبو کې خپل کالي ووینځي او غسل دې وکړي، نو هغه به پاک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_13.mp3', '', 1761754199, 1761754199),
(46167, 'Leviticus 15:14', 'Leviticus', 15, 14, 'هغه باید په اتمه ورځ دوه کوترې یا دوه قمري ګانې واخلي او د څښتن حضور ته دې د سپېڅلې خېمې د دروازې خولې ته راشي او هغه دې کاهن ته ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_14.mp3', '', 1761754199, 1761754199),
(46168, 'Leviticus 15:15', 'Leviticus', 15, 15, 'کاهن دې هغه قرباني کړي، یوه د ګناه د نذرانې دپاره او بله د سوځېدونکې نذرانې دپاره. په دې ډول به کاهن د څښتن په حضور کې د هغه سړي دپاره د هغه د زوې د راوتلو له امله کفاره ادا کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_15.mp3', '', 1761754199, 1761754199),
(46169, 'Leviticus 15:16', 'Leviticus', 15, 16, 'کله چې له یو سړي څخه مني راووځي، هغه باید خپل ټول ځان ووینځي، خو هغه به تر ماښامه پورې ناپاک پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_16.mp3', '', 1761754199, 1761754199),
(46170, 'Leviticus 15:17', 'Leviticus', 15, 17, 'هر هغه شی چې د ټوکر یا څرمنې څخه جوړ شوی وي او مني ورباندې لوېدلي وي باید ووینځل شي، خو هغه به تر ماښامه پورې ناپاک پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_17.mp3', '', 1761754199, 1761754199),
(46171, 'Leviticus 15:18', 'Leviticus', 15, 18, 'سړی او ښځه دواړه باید د یوځای کېدلو څخه وروسته غسل وکړي، خو تر ماښامه پورې به ناپاک پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_18.mp3', '', 1761754199, 1761754199),
(46172, 'Leviticus 15:19', 'Leviticus', 15, 19, 'کله چې یوه ښځه میاشتینۍ ناروغي ولري، هغه اووه ورځې ناپاکه پاتې کیږي. هرڅوک چې دې ښځې ته لاس وروړي، هغه به تر ماښامه پورې ناپاک وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_19.mp3', '', 1761754199, 1761754199),
(46173, 'Leviticus 15:20', 'Leviticus', 15, 20, 'که هغه د خپلې میاشتینۍ ناروغۍ په وخت کې په هر شي باندې کښېني یا ورباندې څملي، هغه شی به ناپاک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_20.mp3', '', 1761754199, 1761754199),
(46174, 'Leviticus 15:24', 'Leviticus', 15, 24, 'که چېرې یو سړی د هغې ښځې سره په هغه وخت کې یوځای شي کله چې د هغې میاشتینۍ ناروغي پیل کیږي، هغه سړی به اووه ورځې ناپاک وي. په هرې بسترې باندې چې هغه څملي هغه بستره به ناپاکه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_24.mp3', '', 1761754199, 1761754199),
(46175, 'Leviticus 15:25', 'Leviticus', 15, 25, 'که چېرې د یوې ښځې څخه د میاشتینۍ ناروغۍ څخه پرته د ډېرو ورځو دپاره وینه بهیږي، یا برسېره په عادي میاشتینۍ ناروغۍ د هغې څخه وینه بهیږي، نو ترڅو پورې چې دا وینه بهیږي، هغه ښځه د میاشتینۍ ناروغۍ په شان ناپاکه پاتې کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_25.mp3', '', 1761754199, 1761754199),
(46176, 'Leviticus 15:26', 'Leviticus', 15, 26, 'په دې موده کې که چېرې هغه په هره بستره باندې څملي او یا په هر شي باندې چې کښېني هغه به ناپاک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_26.mp3', '', 1761754199, 1761754199),
(46177, 'Leviticus 15:27', 'Leviticus', 15, 27, 'هرڅوک چې دغو شیانو ته لاس وروړي هغه به ناپاک شي. هغه باید خپل کالي ووینځي او غسل دې وکړي، خو تر ماښامه پورې به ناپاک پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_27.mp3', '', 1761754199, 1761754199),
(46178, 'Leviticus 15:28', 'Leviticus', 15, 28, 'وروسته له دې چې د هغې وینه ودریږي، باید اووه ورځې صبر وکړي، نو بیا به هغه پاکه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_28.mp3', '', 1761754199, 1761754199),
(46179, 'Leviticus 15:29', 'Leviticus', 15, 29, 'په اتمه ورځ باید هغه ښځه دوه کوترې یا دوه قمري ګانې واخلي او هغه دې د سپېڅلې خېمې د دروازې په خوله کې کاهن ته راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_29.mp3', '', 1761754199, 1761754199),
(46180, 'Leviticus 15:30', 'Leviticus', 15, 30, 'کاهن دې یوه د ګناه د نذرانې دپاره او بله د سوځېدونکې نذرانې دپاره قرباني کړي. په دې ډول به هغه د څښتن په حضور کې د هغې ښځې دپاره د هغې د وینې د بهېدلو د ناپاکۍ په خاطر کفاره ادا کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_30.mp3', '', 1761754199, 1761754199),
(46181, 'Leviticus 15:31', 'Leviticus', 15, 31, 'کله چې ستاسو څخه کوم یو ناپاک وي، باید د اسراییلو د قوم څخه لېرې واوسیږي. که نه، نو زما سپېڅلې خېمه به چې د کمپ په منځ کې ده، ناپاکه شي او ټول قوم به مړ شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus15_verse_31.mp3', '', 1761754199, 1761754199),
(46182, 'Hosea 5:1', 'Hosea', 5, 1, 'څښتن وایي: «ای کاهنانو، دې ته غوږ ونیسئ! ای د اسراییلو مشرانو، پام وکړئ! ای د شاهي کورنۍ خلکو، واورئ! نو اوس به ستاسو په هکله قضاوت کیږي! ځکه چې تاسو بتانو ته په عبادت کولو سره خلک د مصفه په ښار کې په دام او د تابور په غره کې په جال کې راګېر کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea5_verse_1.mp3', '', 1761754199, 1761754199),
(46183, 'Hosea 5:2', 'Hosea', 5, 2, 'ای سرکښه خلکو، تاسو په کنده کې د قربانۍ دپاره ډېر حلال کړي دي، نو زه به تاسو ټولو ته سزا درکوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea5_verse_2.mp3', '', 1761754199, 1761754199),
(46184, 'Hosea 5:3', 'Hosea', 5, 3, 'زه اسراییل پېژنم او هغه زما نه خپل ځان نه شي پټولی. هغې بتانو ته په عبادت کولو سره خپل ځان لکه د فاحشې په شان ناپاکه کړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea5_verse_3.mp3', '', 1761754199, 1761754199),
(46185, 'Hosea 5:4', 'Hosea', 5, 4, 'خلکو چې کوم بد عملونه کړي دي، هغه خدای ته د دوی د بېرته راګرځېدلو مخنیوی کوي. هغوی په سختې بت‌پرستۍ کې راګېر شوي دي او هغوی څښتن نه پېژني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea5_verse_4.mp3', '', 1761754199, 1761754199),
(46186, 'Hosea 5:5', 'Hosea', 5, 5, 'د اسراییلو د خلکو غرور د هغوی په خلاف شاهدي ورکوي. اسراییل د خپلو ګناهونو له امله تیندکونه خوري او د یهودا خلک هم ورسره غورځیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea5_verse_5.mp3', '', 1761754199, 1761754199),
(46187, 'Hosea 5:6', 'Hosea', 5, 6, 'هغوی خپلې رمې او پادې وړي چې څښتن ته یې د قربانیو په توګه وړاندې کړي، خو هغوی څښتن نه شي موندلی، ځکه چې هغوی یې پریښي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea5_verse_6.mp3', '', 1761754199, 1761754199),
(46188, 'Hosea 5:7', 'Hosea', 5, 7, 'هغوی د څښتن سره بې‌وفایي کړې ده. هغوی چې کوم اولادونه راوړي دي، هغه حرامیان دي. نو اوس به د نوې میاشتې نه مخکې هغوی او د هغوی ځمکې زر له منځه لاړې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea5_verse_7.mp3', '', 1761754199, 1761754199),
(46189, 'Hosea 5:8', 'Hosea', 5, 8, 'په جبعه کې د جنګ سرنی ووهئ! په رامه کې د خطر زنګ ووهئ! په بیت‌آون کې د جنګ نارې ووهئ! ای د بنیامین خلکو، جنګ ته لاړ شئ، مونږ درپسې یو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea5_verse_8.mp3', '', 1761754199, 1761754199),
(46190, 'Hosea 5:9', 'Hosea', 5, 9, 'ای د افرایم خلکو، ستاسو د سزا ورځ راروانه ده او ټول به تباه شي. کوم څه چې ما د اسراییلو قبیلو ته ویلي دي، هغه به په رښتیا سره پېښ شي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea5_verse_9.mp3', '', 1761754199, 1761754199),
(46191, 'Hosea 5:10', 'Hosea', 5, 10, 'څښتن وایي: «د یهودا مشران د هغو خلکو په شان دي چې د جایداد د حد نښه بېځایه کوي. نو زه به خپل قهر لکه د سېلاب په شان په هغوی باندې نازل کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea5_verse_10.mp3', '', 1761754199, 1761754199),
(46192, 'Hosea 5:11', 'Hosea', 5, 11, 'په اسراییلو باندې ظلم کیږي او د هغوی په هکله سخت قضاوت شوی دی، ځکه چې هغوی په دې ټینګار کاوه چې د بې‌ګټو بتانو عبادت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea5_verse_11.mp3', '', 1761754199, 1761754199),
(46193, 'Hosea 5:12', 'Hosea', 5, 12, 'زه به لکه د چینجي په شان چې وړۍ له منځه وړي، د اسراییلو خلک تباه کړم او د یهودا کور به لکه د لرګي په شان خوسا کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea5_verse_12.mp3', '', 1761754199, 1761754199),
(46194, 'Hosea 5:13', 'Hosea', 5, 13, 'کله چې اسراییلو خپله ناروغي او یهودا خپل زخمونه ولیدل، نو اسراییل آشور ته لاړل چې د لوی پاچا نه مرسته وغواړي، خو هغه ونه شو کولای چې د هغوی علاج وکړي او یا یې زخمونه روغ کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea5_verse_13.mp3', '', 1761754199, 1761754199),
(46195, 'Hosea 5:14', 'Hosea', 5, 14, 'خو زه به د اسراییلو په خلکو او یهودا باندې لکه د زمري په شان حمله وکړم. زه به په خپله هغوی ټوټې ټوټې کړم. زه به هغوی راکاږم او هېڅوک به نه شي کولای چې هغوی راڅخه خلاص کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea5_verse_14.mp3', '', 1761754199, 1761754199),
(46196, 'Hosea 5:15', 'Hosea', 5, 15, 'زه به تر هغه وخته پورې خپل قوم پرېږدم، ترڅو پورې هغوی په خپلو ګناهونو باندې اقرار وکړي او ما ته راوګرځي. کله چې په هغوی باندې مصیبت راشي، نو زما د پیدا کولو هڅه به وکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/hosea5_verse_15.mp3', '', 1761754199, 1761754199),
(46197, 'Numbers 21:1', 'Numbers', 21, 1, 'د عراد کنعانی پاچا د کنعان په جنوب کې اوسېده او کله چې هغه واورېدل چې اسراییلیان د اتاریم کلي ته راروان دي، هغه ورباندې حمله وکړه او د هغو څخه یې ځینې ونیول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_1.mp3', '', 1761754199, 1761754199),
(46198, 'Numbers 21:2', 'Numbers', 21, 2, 'نو اسراییلیانو څښتن ته نذر ومانه: «که چېرې ته مونږ په دې خلکو باندې بریالي کړې، مونږ به هغوی او د هغوی ښارونه بې له کوم شرط څخه تاته وقف کړو او هغوی به له منځه یوسو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_2.mp3', '', 1761754199, 1761754199),
(46199, 'Numbers 21:3', 'Numbers', 21, 3, 'څښتن د دوی دعا قبوله کړه او د هغوی سره یې مرسته وکړه چې په کنعانیانو باندې بریالي شي. نو اسراییلیانو هغوی او د هغوی ښارونه بیخي له منځه یووړل او هغه ځای یې د حرمه په نوم یاد کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_3.mp3', '', 1761754199, 1761754199),
(46200, 'Numbers 21:4', 'Numbers', 21, 4, 'اسراییلیان د هور د غره څخه لاړل او په هغې لارې باندې روان شول چې سرې بحیرې ته تللې ده، د دې دپاره چې د ادوم د سیمې په شاوخوا باندې راوګرځي. خو خلکو په لاره کې خپله حوصله له لاسه ورکړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_4.mp3', '', 1761754199, 1761754199),
(46201, 'Numbers 21:5', 'Numbers', 21, 5, 'او د خدای او موسی په خلاف یې خبرې وکړې. هغوی شکایت وکړ: «مونږه مو ولې د مصر څخه راوویستلو چې په دې دښته کې مړه شو، چېرته چې نه ډوډۍ شته او نه اوبه؟ مونږ نور د دې خراب خوراک څخه تنګ شوي یو!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_5.mp3', '', 1761754199, 1761754199),
(46202, 'Numbers 21:6', 'Numbers', 21, 6, 'بیا څښتن په هغوی باندې زهر لرونکي ماران نازل کړل او ډېر اسراییلیان یې وچیچل او مړه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_6.mp3', '', 1761754199, 1761754199),
(46203, 'Numbers 21:7', 'Numbers', 21, 7, 'خلک موسی ته ورغلل او ویې ویل: «مونږ ګناه کړې ده چې د څښتن او ستا په ضد مو خبرې کړې دي. اوس څښتن ته دعا وکړه چې دا ماران لېرې کړي.» نو موسی د خلکو دپاره دعا وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_7.mp3', '', 1761754199, 1761754199),
(46204, 'Numbers 21:8', 'Numbers', 21, 8, 'څښتن موسی ته وویل: «یو فلزي مار جوړ کړه او د یوې پایې په سر باندې یې ځوړند کړه. هرڅوک چې چیچل کیږي، نو کله چې هغه فلزي مار ته وګوري ژوندی به پاتې کیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_8.mp3', '', 1761754199, 1761754199),
(46205, 'Numbers 21:9', 'Numbers', 21, 9, 'نو موسی یو برنجي مار جوړ کړ او هغه یې د یوې پایې په سر باندې ځوړند کړ. هرڅوک به چې مار چیچه هغه به برنجي مار ته کتل، نو ژوندی به پاتې کېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_9.mp3', '', 1761754199, 1761754199),
(46206, 'Numbers 21:10', 'Numbers', 21, 10, 'اسراییلیان روان شول او د اوبوت سره یې خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_10.mp3', '', 1761754199, 1761754199),
(46207, 'Numbers 21:11', 'Numbers', 21, 11, 'کله چې هغوی د هغه ځای څخه لاړل، د عیی عباریم په دښته کې د موآب د سیمې ختیځ خواته یې خېمې ودرولې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_11.mp3', '', 1761754199, 1761754199),
(46208, 'Numbers 21:12', 'Numbers', 21, 12, 'بیا یې د زارد د خوړ په څنګ کې خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_12.mp3', '', 1761754199, 1761754199),
(46209, 'Numbers 21:13', 'Numbers', 21, 13, 'بیا د هغه ځای څخه روان شول او د ارنون د سیند په شمال کې په هغې دښتې کې یې چې د اموریانو تر سیمې پورې غزېدلې ده، خېمې ودرولې. (ارنون د موآبیانو او اموریانو ترمنځ سرحد ؤ.)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_13.mp3', '', 1761754199, 1761754199),
(46210, 'Numbers 21:14', 'Numbers', 21, 14, 'له همدې امله د څښتن د جنګونو په کتاب کې ویل شوي دي چې د واهیب ښار او د هغه ویالې د سوفه په سیمه کې دي، د ارنون سیند او', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers21_verse_14.mp3', '', 1761754199, 1761754199);